<?php if($kind==='debts'):$extra=is_string($_GET['extra']??'')?($_GET['extra']??'0'):'0';$extra=cents($extra===''?'0':$extra,true)/100; ?><section class="card"><h2><?= e(t('Compare debt strategies')) ?></h2><form class="inline" method="get" action="/life"><input type="hidden" name="page" value="debts"><label><?= e(t('Extra monthly budget')) ?><input type="number" name="extra" min="0" step="0.01" value="<?= e($extra) ?>"></label><button><?= e(t('Compare')) ?></button></form><p><?= e(t('Monthly budget keeps the original minimum payments plus this extra. Freed minimums roll into the next debt. Rates stay constant; fees are excluded.')) ?></p><?php foreach(['snowball','avalanche']as $strategy):$r=LifeFinanceMath::debtPayoff($rows,$extra,$strategy); ?><h3><?= e(ucfirst($strategy)) ?></h3><p><?= $r['paid_off']?e($r['months']).' months to payoff':t('Not paid off within the bounded projection') ?> <?= e(t('· Interest')) ?> <?= money($r['interest']) ?> <?= e(t('· Remaining')) ?> <?= money($r['remaining']) ?></p><details><summary><?= e(t('Monthly schedule')) ?></summary><div class="table-wrap"><table><tr><th><?= e(t('Month')) ?></th><th><?= e(t('Interest')) ?></th><th><?= e(t('Payment')) ?></th><th><?= e(t('Remaining')) ?></th></tr><?php foreach($r['rows']as $line): ?><tr><td><?= e($line['month']) ?></td><td><?= money($line['interest']) ?></td><td><?= money($line['payment']) ?></td><td><?= money($line['remaining']) ?></td></tr><?php endforeach; ?></table></div></details><?php endforeach; ?><a href="/salary/plan"><?= e(t('Review emergency-fund plan')) ?></a></section><?php endif; ?>
<?php if($kind==='food_budgets'||$kind==='groceries'): ?><section class="card"><h2><?= e(t('Food spending by month')) ?></h2><?php foreach(LifePlanningService::rows('food_budgets')as $b):$spent=0;foreach(LifePlanningService::rows('groceries')as $g)if($g['bought']&&substr($g['purchased_on']??'',0,7)===$b['month'])$spent+=$g['actual_cost']; ?><p><?= e($b['month']) ?> <?= e(t('· Actual')) ?> <?= money($spent) ?> <?= e(t('/ Budget')) ?> <?= money($b['budget']) ?> <?= e(t('· Remaining')) ?> <?= money($b['budget']-$spent) ?></p><?php endforeach; ?></section><?php endif; ?>
<?php if($kind==='utilities'||$kind==='readings'): ?><section class="card"><h2><?= e(t('Usage trends')) ?></h2><?php foreach(LifePlanningService::rows('utilities')as $utility):$series=array_values(array_filter(LifePlanningService::rows('readings'),fn($r)=>$r['utility_id']===$utility['id']));usort($series,fn($a,$b)=>strcmp($a['reading_on'],$b['reading_on'])); ?><h3><?= e($utility['provider']) ?></h3><?php if(count($series)>=2):$last=$series[count($series)-1];$previous=$series[count($series)-2]; ?><p><?= e(t('Latest bill')) ?> <?= money($last['amount']) ?> <?= e(t('· Change')) ?> <?= money($last['amount']-$previous['amount']) ?><?= $last['usage']!==null&&$previous['usage']!==null?' · Usage change '.e(round($last['usage']-$previous['usage'],3)):'' ?></p><?php endif; ?><?= chart('line',array_column($series,'reading_on'),[['label'=>t('Recorded usage'),'data'=>array_column($series,'usage'),'borderColor'=>'#3578e5']]) ?><?php endforeach; ?></section><?php endif; ?>
